#include <iostream>
#include <string>
#include <algorithm>
using namespace std;
int main(){
    int g;
    while (cin >> g && g != 0) {
        int lo = 1, hi = 10;
        bool dishonest = false;
        while (true) {
            string w1, w2;
            cin >> w1 >> w2;
            if (w1 == "right") {
                if (g < lo || g > hi) dishonest = true;
                break;
            }
            if (w2 == "high") hi = min(hi, g - 1);
            else lo = max(lo, g + 1);
            if (lo > hi) dishonest = true;
            cin >> g;
        }
        cout << (dishonest ? "Stan is dishonest" : "Stan may be honest") << "\n";
    }
}

